	| 'LocrianNat6'
	| 'IonianAug'
	| 'DorianSharp4'
	| 'PhrygianDominant'
	| 'LydianSharp2'
	| 'SuperLocrianDim'
	// Melodic Minor (7)
	| 'MelodicMinor'
	| 'DorianFlat2'
	| 'LydianAug'
	| 'LydianDominant'
	| 'MixolydianFlat6'
	| 'LocrianNat2'
	| 'SuperLocrian'
	// Harmonic Major (7)
	| 'HarmonicMajor'
	| 'DorianFlat5'
	| 'PhrygianFlat4'
	| 'LydianFlat3'
	| 'MixolydianFlat2'
