/**
 * Engine Store — Reactive Harmony Engine State (Svelte 5 Runes)
 *
 * Tracks the harmony engine configuration and real-time note state.
 * All mutations call the platform adapter and update local state
 * optimistically (set locally, then call backend; revert on error).
 */

import { adapter } from '$lib/adapter';
import type { NoteState } from '$lib/adapter';

/** Compare two note arrays (order-independent) to avoid unnecessary Svelte re-renders.
 *  HashSet iteration order is non-deterministic, so we must sort before comparing. */
function sameNotes(a: number[], b: number[]): boolean {
	if (a.length !== b.length) return false;
	if (a.length === 0) return true;
	// Sort copies to compare regardless of HashSet ordering
	const sa = [...a].sort();
	const sb = [...b].sort();
	for (let i = 0; i < sa.length; i++) {
		if (sa[i] !== sb[i]) return false;
	}
	return true;
}

// === Type definitions ===

export type KeyName =
	| 'C'
	| 'C#'
	| 'D'
	| 'D#'
	| 'E'
	| 'F'
	| 'F#'
	| 'G'
	| 'G#'
	| 'A'
	| 'A#'
	| 'B';

export type HarmonyModeName =
	| 'PassThrough'
	| 'DiatonicThirds'
	| 'DiatonicFourths'
	| 'RandomBelow'
	| 'RandomBelowNoSeconds'
	| 'ContraryMotion'
	| 'StrictCounterpoint'
	| 'BarryHarris'
	| 'FunctionalHarmony'
	| 'BachChorale';

export type ScaleFamilyName =
	| 'Diatonic'
	| 'HarmonicMinor'
	| 'MelodicMinor'
	| 'HarmonicMajor'
	| 'DoubleHarmonic'
	| 'Pentatonic'
	| 'Blues'
	| 'Symmetric'
	| 'World'
	| 'BarryHarris';

export type ScaleModeName =
	// Diatonic (7)
	| 'Ionian'
	| 'Dorian'
	| 'Phrygian'
	| 'Lydian'
	| 'Mixolydian'
	| 'Aeolian'
	| 'Locrian'
	// Harmonic Minor (7)
	| 'HarmonicMinor'
	| 'LocrianNat6'
	| 'IonianAug'
	| 'DorianSharp4'
	| 'PhrygianDominant'
	| 'LydianSharp2'
	| 'SuperLocrianDim'
	// Melodic Minor (7)
	| 'MelodicMinor'
	| 'DorianFlat2'
	| 'LydianAug'
	| 'LydianDominant'
	| 'MixolydianFlat6'
	| 'LocrianNat2'
	| 'SuperLocrian'
	// Harmonic Major (7)
	| 'HarmonicMajor'
	| 'DorianFlat5'
	| 'PhrygianFlat4'
	| 'LydianFlat3'
	| 'MixolydianFlat2'
	| 'LydianAugSharp2'
	| 'LocrianDoubleFlat7'
	// Double Harmonic (7)
	| 'DoubleHarmonic'
	| 'LydianSharp2Sharp6'
	| 'Ultraphrygian'
	| 'HungarianMinor'
	| 'Oriental'
	| 'IonianSharp2Sharp5'
	| 'LocrianDoubleFlat3DoubleFlat7'
	// Pentatonic (8)
	| 'MajorPentatonic'
	| 'MinorPentatonic'
	| 'Hirajoshi'
	| 'InSen'
	| 'Iwato'
	| 'Yo'
	| 'Kumoi'
	| 'Pelog'
	// Blues & Bebop (3)
	| 'MinorBlues'
	| 'MajorBlues'
	| 'BebopDominant'
	// Symmetric (4)
	| 'WholeTone'
	| 'DiminishedWholeHalf'
	| 'DiminishedHalfWhole'
	| 'AugmentedHex'
	// World (5)
	| 'Enigmatic'
	| 'NeapolitanMinor'
	| 'NeapolitanMajor'
	| 'Persian'
	| 'HungarianMajor'
	// Barry Harris (2)
	| 'BHMajor6thDim'
	| 'BHMinor6thDim';

export type OctaveModeName = 'None' | 'Spread' | 'BassTrebleSplit' | 'Mirror';

export type VoiceLeadingStyleName = 'Free' | 'Palestrina' | 'BachChorale' | 'Jazz';

export type CounterpointSpeciesName =
	| 'Species1'
	| 'Species2'
	| 'Species3'
	| 'Species4';

export type CounterpointStrictnessName = 'Relaxed' | 'Strict';

export type ImitativeFormName = 'strict_canon' | 'free_imitation';

export const COUNTERPOINT_SPECIES: {
	name: CounterpointSpeciesName;
	label: string;
	shortLabel: string;
	tooltip: string;
}[] = [
	{
		name: 'Species1',
		label: 'Species 1 (1:1)',
		shortLabel: 'I',
		tooltip: 'Note-against-note. One harmony note per melody note.'
	},
	{
		name: 'Species2',
		label: 'Species 2 (2:1)',
		shortLabel: 'II',
		tooltip: 'Two harmony notes per melody note; passing tones on weak beats.'
	},
	{
		name: 'Species3',
		label: 'Species 3 (4:1)',
		shortLabel: 'III',
		tooltip: 'Four harmony notes per melody note; figuration on weak beats.'
	},
	{
		name: 'Species4',
		label: 'Species 4 (Susp.)',
		shortLabel: 'IV',
		tooltip: 'Syncopated harmony: prepare / suspend / resolve.'
	}
];

export const COUNTERPOINT_STRICTNESS: {
	name: CounterpointStrictnessName;
	label: string;
	tooltip: string;
}[] = [
	{
		name: 'Relaxed',
		label: 'Relaxed',
		tooltip: 'Lighter penalties — more permissive harmonic choices.'
	},
	{
		name: 'Strict',
		label: 'Strict',
