/**
 * UI Store -- Reactive UI Preferences (Svelte 5 Runes)
 *
 * Manages UI preferences like animations, reduced motion, theme,
 * and platform detection. Persists preferences where possible.
 */

import { platformName } from '$lib/adapter';

// === Persistence ===

const SCALE_KEY = 'contrapunk-ui-scale';
const FONT_SCALE_KEY = 'contrapunk-font-scale';
const NOTE_LABELS_KEY = 'contrapunk-show-note-labels';
const NOTE_LINGERING_KEY = 'contrapunk-note-lingering';
const PANELS_KEY = 'contrapunk-panels';
const VIEW_MODE_KEY = 'contrapunk-view-mode';
const ACTIVE_TAB_KEY = 'contrapunk-active-tab';
const IO_SUBTAB_KEY = 'contrapunk-io-subtab';

const MIN_SCALE = 0.75;
const MAX_SCALE = 2.0;
const MIN_FONT_SCALE = 0.75;
const MAX_FONT_SCALE = 1.5;

/** Panels the user can show/hide independently. The 'midi' panel was
 *  removed in the I/O tab restructure — the MIDI device picker, guitar
 *  input panel, calibration card, and per-voice routing all live in the
 *  I/O tab now (Input + Output subtabs), so the Harmony tab no longer
 *  needs a MIDI column. Old saves with `panels.midi: false` migrate
 *  silently (the unknown id is ignored on restore). */
export type PanelId =
	| 'controls'
	| 'activeNotes'
	| 'lines'
	| 'history'
	| 'fretboard'
	| 'piano';

export const PANELS: { id: PanelId; label: string }[] = [
	{ id: 'controls', label: 'Controls' },
	{ id: 'activeNotes', label: 'Notes' },
	{ id: 'lines', label: 'Lines' },
	{ id: 'history', label: 'History' },
	{ id: 'fretboard', label: 'Fret' },
	{ id: 'piano', label: 'Piano' }
];

export type PanelVisibility = Record<PanelId, boolean>;

const DEFAULT_PANELS: PanelVisibility = {
	controls: true,
	activeNotes: true,
	lines: true,
	history: false,
	fretboard: false,
	piano: false
};

/** Top-level layout choice: the simplified 8-knob Performance view vs.
 *  the full Advanced surface (today's UI). Orthogonal to `activeTab`
 *  ('play' vs 'chain') and to the Play-tab `panels` toggles — view mode
 *  picks WHICH layout, panels pick WHICH bits of the Advanced layout
 *  render. The Performance view ignores `panels` entirely. */
export type ViewMode = 'performance' | 'advanced';

/** Top-level tab options. The legacy 'chain' tab was removed during the
 *  v1.3 I/O restructure — its content now lives inside the I/O Output
 *  subtab as the Voice Generation Chain + synth/FX racks. */
export type ActiveTab = 'play' | 'io' | 'companion' | 'voices';

/** I/O tab subtabs. 'input' hosts the source pickers (MIDI / Guitar /
 *  Voice-disabled) + calibration. 'output' is the Voice Generation Chain
 *  visualization + synth/FX racks. */
export type IoSubtab = 'input' | 'output';

// === UI Store (Svelte 5 runes) ===

