			} else if (tab === 'chain') {
				// Legacy migration: the Chain tab merged into I/O Output.
				// Use the setters so the localStorage entry overwrites
				// 'chain' on the same restore (avoids re-migrating on
				// every subsequent launch). Flag the migration so we
				// don't subsequently overwrite ioSubtab='output' with a
				// stale localStorage 'input' value (brutal-critic #1).
				this.setActiveTab('io');
				this.setIoSubtab('output');
				migrated = true;
			}
			if (!migrated) {
				const sub = localStorage.getItem(IO_SUBTAB_KEY);
				if (sub === 'input' || sub === 'output') {
					this.ioSubtab = sub;
				}
			}
		} catch {
			/* localStorage unavailable */
		}
	}

	/** Hydrate viewMode from localStorage. Falls back to default if no
	 *  saved value or value is unrecognized (e.g. forward-compat). */
	restoreViewMode() {
		if (typeof window === 'undefined') return;
		try {
			const raw = localStorage.getItem(VIEW_MODE_KEY);
			if (raw === 'performance' || raw === 'advanced') {
				this.viewMode = raw;
			}
		} catch {
			/* localStorage unavailable */
		}
	}

	/** Hydrate the panel record from localStorage. Unknown ids are
	 *  ignored; missing ids fall back to the default-true state so
	 *  upgrades that introduce new panels don't accidentally hide
	 *  them on existing installs. */
	restorePanels() {
		if (typeof window === 'undefined') return;
		try {
			const raw = localStorage.getItem(PANELS_KEY);
			if (!raw) return;
			const parsed = JSON.parse(raw);
			if (!parsed || typeof parsed !== 'object') return;
			const next: PanelVisibility = { ...DEFAULT_PANELS };
			for (const { id } of PANELS) {
