			}
			// Before Live Lines existed, the default saved all three legacy
			// visualizations as visible. Migrate only that exact old default
			// to the new progressive anchor; preserve any deliberate custom
			// combination the user already chose.
			if (
				typeof parsed.lines !== 'boolean' &&
				parsed.history === true &&
				parsed.fretboard === true &&
				parsed.piano === true
			) {
				next.history = false;
				next.fretboard = false;
				next.piano = false;
				this.panels = next;
				this.persistPanels();
				return;
			}
			this.panels = next;
		} catch {
			/* localStorage unavailable or corrupt JSON */
		}
	}

	/** Restore persisted appearance preferences from localStorage.
	 *  Font family is no longer user-configurable — the app is locked
	 *  to the website's typography pair (Space Grotesk + JetBrains Mono).
	 *  Also cleans up the legacy `contrapunk-ui-font` key + any stale
