     1	<script lang="ts">
     2		import ControlPanel from '$lib/components/ControlPanel.svelte';
     3		import Piano from '$lib/components/Piano.svelte';
     4		import PerformanceView from '$lib/components/PerformanceView.svelte';
     5		// PresetManager temporarily unmounted (backend + component file
     6		// kept). Tracked in contrapunk#65 — will return with a redesigned UX.
     7		import ActiveNotes from '$lib/components/ActiveNotes.svelte';
     8		import Fretboard from '$lib/components/Fretboard.svelte';
     9		import HistoryStrip from '$lib/components/HistoryStrip.svelte';
    10		import LiveLines from '$lib/components/LiveLines.svelte';
    11		import SettingsModal from '$lib/components/SettingsModal.svelte';
    12		import CompanionPanel from '$lib/components/CompanionPanel.svelte';
    13		import VoicesPanel from '$lib/components/VoicesPanel.svelte';
    14		import InputPanel from '$lib/components/InputPanel.svelte';
    15		import OutputPanel from '$lib/components/OutputPanel.svelte';
    16		import PluginWorkspace from '$lib/components/PluginWorkspace.svelte';
    17		import { adapter } from '$lib/adapter';
    18		import { engine } from '$lib/stores/engine.svelte';
    19		import { midi } from '$lib/stores/midi.svelte';
    20		import { ui } from '$lib/stores/ui.svelte';
    21		import { synth } from '$lib/stores/synth.svelte';
    22		import { transport } from '$lib/stores/transport.svelte';
    23		import { attachKeyboardInput } from '$lib/keyboard-input';
    24	
    25		// Virtual input sentinel — referenced by the keyboard-input gate
    26		// and the FTUX auto-selection path. Must match the values in
    27		// src-tauri/src/commands/engine.rs.
    28		const VIRTUAL_COMPUTER_KEYBOARD = 999_998;
    29	
    30		// QWERTY keyboard input — see $lib/keyboard-input for the keymap.
    31	
    32		// Initialize adapter, sync engine state, and enumerate MIDI devices on mount
    33		let initError = $state<string | null>(null);
    34		let initDone = $state(false);
    35		let initStarted = false;
    36	
    37		$effect(() => {
    38			if (initStarted) return;
    39			initStarted = true;
    40	
    41			(async () => {
    42				try {
    43					ui.restoreAppearance();
    44					ui.restorePanels();
    45					ui.restoreViewMode();
    46					ui.restoreTabs();
    47					await adapter.init();
    48					await engine.syncFromBackend();
    49					if (adapter.capabilities.pluginMidiOutputMode) {
    50						await engine.restoreCompanionSettings();
    51					} else {
    52						await engine.restoreSettings();
    53					}
    54					// Browser path: only refreshes devices if the user previously
    55					// granted Web MIDI access. First-time visitors see the
    56					// "Enable MIDI" button in MidiPermissionCard.svelte instead.
    57					// Tauri / Plugin: resolves immediately and refreshes.
    58					await midi.hydratePermission();
    59					await synth.syncFromBackend();
    60					// Force the metronome OFF on every fresh launch. Backend
    61					// AppState already defaults `metronome_enabled` to false,
    62					// but explicitly resetting here defends against any
    63					// startup race condition (audio thread firing a beat
    64					// crossing before the UI's syncFromBackend completes) and
    65					// guarantees the user never gets a click on first boot.
    66					try {
    67						await transport.setMetronomeEnabled(false);
    68					} catch {
    69						/* no transport adapter (browser w/o backend) */
    70					}
    71	
    72					// FTUX:
    73					// - No saved input → default to Computer Keyboard (the
    74					//   user gets audible notes from typing immediately).
    75					// - Saved Guitar Audio → reset to Computer Keyboard.
    76					//   Auto-starting with guitar would open the mic as a
    77					//   hot input on launch (the audio device picked up
    78					//   ambient sound, possibly with default-untrimmed gain).
    79					//   Guitar requires explicit configuration (device,
    80					//   channel, calibration) and should be opt-in per
    81					//   session via the I/O tab.
    82					// - Saved real MIDI device → keep it (user previously
    83					//   wired up a controller; respect that).
    84					try {
    85						const GUITAR_SENTINEL = 999_997;
    86						if (
    87							midi.selectedInput === null ||
    88							midi.selectedInput === GUITAR_SENTINEL
    89						) {
    90							midi.selectVirtualInput(VIRTUAL_COMPUTER_KEYBOARD);
    91						}
    92						if (!engine.isRunning && midi.selectedInput !== null) {
    93							await engine.start(midi.selectedInput, midi.selectedOutputs);
    94						}
    95					} catch (e) {
    96						console.warn('[contrapunk] FTUX auto-routing skipped:', e);
    97					}
    98	
    99					initDone = true;
   100				} catch (e) {
   101					initError = `Init failed: ${e}`;
   102					console.error('[contrapunk] Initialization error:', e);
   103				}
   104			})();
   105		});
   106	
   107		// Computer-Keyboard virtual input — wired via the shared keymap
   108		// in $lib/keyboard-input. Gated on Computer-Keyboard being the
   109		// selected input AND the engine running, so other input modes
   110		// (real MIDI, Guitar Audio) keep ignoring keystrokes.
   111		$effect(() =>
   112			attachKeyboardInput({
   113				onNoteOn: (midi) => {
   114					adapter.injectNoteOn(midi, 100);
   115				},
   116				onNoteOff: (midi) => {
   117					adapter.injectNoteOff(midi);
   118				},
   119				enabled: () =>
   120					midi.selectedInput === VIRTUAL_COMPUTER_KEYBOARD && engine.isRunning
   121			})
   122		);
   123	
   124		// Music-reactive: detect when notes are actively sounding
   125		let hasActiveNotes = $derived(
   126			engine.inputNotes.length > 0 || engine.harmonyNotes.length > 0
   127		);
   128		let manyNotesActive = $derived(
   129			engine.inputNotes.length + engine.harmonyNotes.length >= 4
   130		);
   131	
   132		// WAI-ARIA tablist keyboard navigation. ArrowLeft/ArrowRight cycle
   133		// through tabs; Home / End jump to ends. Roving-tabindex pattern.
   134		type MainTab = 'play' | 'io' | 'companion' | 'voices';
   135		const MAIN_TABS: MainTab[] = ['play', 'io', 'companion', 'voices'];
   136	
   137		function focusTab(id: string) {
   138			document.getElementById(id)?.focus();
   139		}
   140	
   141		/** Defer focus until the DOM has the new tabindex applied. Use
   142		 *  requestAnimationFrame instead of queueMicrotask — Svelte 5
   143		 *  effects flush in the same microtask queue, and on Safari the
   144		 *  microtask-vs-DOM-update order is unreliable for focus targets
   145		 *  that just had their tabindex flipped from -1 to 0. rAF is the
   146		 *  pattern the WAI-ARIA APG examples use.
   147		 *
   148		 *  Cancel any pending focus before scheduling new — mashed arrow
   149		 *  keys would otherwise queue N callbacks per frame, each focusing
   150		 *  an intermediate tab. Visually the user only sees the last
   151		 *  movement, but a screen reader announces every intermediate
   152		 *  focus change (a11y noise). Round-3 critic. */
   153		let pendingFocus: number | null = null;
   154		function deferFocus(id: string) {
   155			if (typeof requestAnimationFrame !== 'function') {
   156				focusTab(id);
   157				return;
   158			}
   159			if (pendingFocus !== null) {
   160				cancelAnimationFrame(pendingFocus);
   161			}
   162			pendingFocus = requestAnimationFrame(() => {
   163				pendingFocus = null;
   164				focusTab(id);
   165			});
   166		}
   167	
   168		function handleTabKeydown(e: KeyboardEvent, current: MainTab) {
   169			const idx = MAIN_TABS.indexOf(current);
   170			if (idx < 0) return;
   171			let next = idx;
   172			if (e.key === 'ArrowRight') next = (idx + 1) % MAIN_TABS.length;
   173			else if (e.key === 'ArrowLeft') next = (idx - 1 + MAIN_TABS.length) % MAIN_TABS.length;
   174			else if (e.key === 'Home') next = 0;
   175			else if (e.key === 'End') next = MAIN_TABS.length - 1;
   176			else return;
   177			e.preventDefault();
   178			const target = MAIN_TABS[next];
   179			ui.setActiveTab(target);
   180			deferFocus(`tab-${target}`);
   181		}
   182	
   183		function handleSubtabKeydown(e: KeyboardEvent, current: 'input' | 'output') {
   184			if (e.key !== 'ArrowRight' && e.key !== 'ArrowLeft' && e.key !== 'Home' && e.key !== 'End') {
   185				return;
   186			}
   187			e.preventDefault();
   188			const next: 'input' | 'output' = current === 'input' ? 'output' : 'input';
   189			ui.setIoSubtab(next);
   190			deferFocus(`subtab-${next}`);
   191		}
   192	</script>
