     1	/**
     2	 * Platform Adapter — Factory and Export
     3	 *
     4	 * Detects the runtime platform (Tauri desktop vs browser) and
     5	 * exports the appropriate adapter implementation as a singleton.
     6	 */
     7	
     8	import type { ContrapunkAdapter } from './types';
     9	import { TauriAdapter } from './tauri';
    10	import { WasmAdapter } from './wasm';
    11	import { PluginAdapter } from './plugin';
    12	
    13	/**
    14	 * Detect whether we are running inside a nih-plug-webview plugin.
    15	 * The webview injects `window.plugin` with send/listen/resize methods.
    16	 */
    17	function isPlugin(): boolean {
    18		return typeof window !== 'undefined' && 'plugin' in window && typeof window.plugin?.send === 'function';
    19	}
    20	
    21	/**
    22	 * Detect whether we are running inside a Tauri webview.
    23	 *
    24	 * Tauri v2 only injects `__TAURI_INTERNALS__` by default.
    25	 * The `__TAURI__` global requires `withGlobalTauri: true` in
    26	 * tauri.conf.json, which is not set. Check both to be safe.
    27	 */
    28	function isTauri(): boolean {
    29		return (
    30			typeof window !== 'undefined' &&
    31			('__TAURI_INTERNALS__' in window || '__TAURI__' in window)
    32		);
    33	}
    34	
    35	/** The active platform name, for display purposes. */
    36	export const platformName: 'tauri' | 'browser' | 'plugin' = isPlugin()
    37		? 'plugin'
    38		: isTauri()
    39			? 'tauri'
    40			: 'browser';
    41	
    42	/**
    43	 * Singleton adapter instance.
    44	 *
    45	 * Components import this and call methods without knowing the backend:
    46	 * ```ts
    47	 * import { adapter } from '$lib/adapter';
    48	 * await adapter.setKey('C');
    49	 * ```
    50	 */
    51	export const adapter: ContrapunkAdapter = isPlugin()
    52		? new PluginAdapter()
    53		: isTauri()
    54			? new TauriAdapter()
    55			: new WasmAdapter();
    56	
    57	// Re-export types for convenience
    58	export type {
    59		ContrapunkAdapter,
    60		EngineState,
    61		GuitarConfig,
    62		MidiDevice,
    63		MidiPermissionState,
    64		NoteState,
    65		Preset,
    66		SynthState,
    67		TransportState,
    68		VoiceOutputTarget
    69	} from './types';
    70	export { MAX_VOICES } from './types';

