    28	            // Start the audio clock: a cpal output stream that ticks the
    29	            // Transport, emits `beat-update` events, synthesizes metronome
    30	            // clicks, and renders the built-in synth.
    31	            let state = app.state::<AppState>();
    32	            let transport = Arc::clone(&state.transport);
    33	            let metronome_enabled = Arc::clone(&state.metronome_enabled);
    34	            let synth_params = Arc::clone(&state.synth_params);
    35	            let synth_rx = state
    36	                .synth_rx
    37	                .lock()
    38	                .ok()
    39	                .and_then(|mut guard| guard.take());
    40	            let reverb_params = Arc::clone(&state.reverb_params);
    41	            let delay_params = Arc::clone(&state.delay_params);
    42	            match audio_clock::start(
    43	                app.handle().clone(),
    44	                transport,
    45	                metronome_enabled,
    46	                synth_params,
    47	                synth_rx,
    48	                reverb_params,
    49	                delay_params,
    50	            ) {
    51	                Ok(commander) => {
    52	                    if let Ok(mut slot) = state.chain_commander.lock() {
    53	                        *slot = Some(commander);
    54	                    }
    55	                    // FTUX: auto-start the transport so canon-companion
    56	                    // voices fire from the first note. Metronome stays
    57	                    // off by default — the clock ticks silently until
    58	                    // the user enables it.
    59	                    state.transport.play();
    60	                }
    61	                Err(e) => {
    62	                    eprintln!(
    63	                        "[main] audio_clock::start failed: {} (transport will not tick)",
    64	                        e
    65	                    );
    66	                }
    67	            }
    68	
    69	            // Startup auto-load of the guitar calibration profile, if
    70	            // present at `~/Library/Application Support/com.contrapunk.app/
    71	            // guitar_calibration_profile.json` (or platform equivalent).
    72	            // Brutal-critic #18 found the previous behavior silently
    73	            // ignored a saved profile on every launch until the user
    74	            // clicked Reload. Now the profile is picked up immediately so
    75	            // the first guitar routing session uses the calibrated
    76	            // thresholds. Errors are logged but don't fail setup —
    77	            // a missing or broken profile must not block app startup.
    78	            let handle = app.handle().clone();
    79	            match commands::guitar::apply_calibration_profile_from_disk(&handle, &state) {
    80	                Ok(_) => {}
    81	                Err(e) => eprintln!("[main] calibration auto-load skipped: {}", e),
    82	            }
