  1596	fn build_guitar_signal_payload(sig: crate::guitar_bridge::GuitarSignalInfo) -> GuitarSignalPayload {
  1597	    const NOTE_NAMES: [&str; 12] = [
  1598	        "C", "C#", "D", "Eb", "E", "F", "F#", "G", "Ab", "A", "Bb", "B",
  1599	    ];
  1600	    let (note_name, midi_note) = if let Some(freq) = sig.frequency {
  1601	        if freq > 20.0 && sig.clarity > 0.3 {
  1602	            let midi = (12.0 * (freq / 440.0).log2() + 69.0).round() as i32;
  1603	            let midi_u8 = midi.clamp(0, 127) as u8;
  1604	            let name_idx = (midi_u8 % 12) as usize;
  1605	            let octave = (midi_u8 as i32 / 12) - 1;
  1606	            (format!("{}{}", NOTE_NAMES[name_idx], octave), midi_u8)
  1607	        } else {
  1608	            (String::new(), 0)
  1609	        }
  1610	    } else {
  1611	        (String::new(), 0)
  1612	    };
  1613	    GuitarSignalPayload {
  1614	        rms: sig.rms,
  1615	        frequency: sig.frequency,
  1616	        clarity: sig.clarity,
  1617	        note_state: sig.note_state,
  1618	        note_name,
  1619	        midi_note,
  1620	    }
  1621	}
