pub use self::parse::parse;

fn default_true() -> bool {
  true
}

/// An URL to open on a Tauri webview window.
#[derive(PartialEq, Eq, Debug, Clone, Serialize)]
#[cfg_attr(feature = "schema", derive(JsonSchema))]
#[serde(untagged)]
#[non_exhaustive]
pub enum WebviewUrl {
  /// An external URL. Must use either the `http` or `https` schemes.
  External(Url),
  /// The path portion of an app URL.
  /// For instance, to load `tauri://localhost/users/john`,
  /// you can simply provide `users/john` in this configuration.
  App(PathBuf),
  /// A custom protocol url, for example, `doom://index.html`
  CustomProtocol(Url),
}

impl<'de> Deserialize<'de> for WebviewUrl {
  fn deserialize<D>(deserializer: D) -> std::result::Result<Self, D::Error>
  where
    D: Deserializer<'de>,
  {
    #[derive(Deserialize)]
    #[serde(untagged)]
    enum WebviewUrlDeserializer {
      Url(Url),
      Path(PathBuf),
    }

    match WebviewUrlDeserializer::deserialize(deserializer)? {
      WebviewUrlDeserializer::Url(u) => {
        if u.scheme() == "https" || u.scheme() == "http" {
          Ok(Self::External(u))
        } else {
          Ok(Self::CustomProtocol(u))
        }
      }
      WebviewUrlDeserializer::Path(p) => Ok(Self::App(p)),
    }
  }
}

impl fmt::Display for WebviewUrl {
  fn fmt(&self, f: &mut fmt::Formatter<'_>) -> fmt::Result {
    match self {
     1	<script lang="ts">
     2		import { ui } from '$lib/stores/ui.svelte';
     3		import { onDestroy } from 'svelte';
     4	
     5		/**
     6		 * HLD Atmospheric Particle System
     7		 *
     8		 * Renders 30 small ambient dots drifting slowly in magenta/cyan/teal
     9		 * behind all UI content. Uses a canvas element for efficient rendering
    10		 * with minimal CPU cost. Respects ui.animationsEnabled.
    11		 */
    12	
    13		const PARTICLE_COUNT = 30;
    14		const COLORS = [
    15			'rgba(255, 51, 136, 0.2)',   // magenta
    16			'rgba(51, 221, 255, 0.2)',   // cyan
    17			'rgba(0, 204, 170, 0.2)',    // teal
    18			'rgba(255, 119, 170, 0.15)', // soft pink
    19			'rgba(51, 221, 255, 0.12)',  // faint cyan
    20		];
    21	
    22		interface Particle {
    23			x: number;
    24			y: number;
    25			vx: number;
    26			vy: number;
    27			size: number;
    28			color: string;
    29			opacity: number;
    30			opacitySpeed: number;
    31			opacityDir: number;
    32		}
    33	
    34		let canvas: HTMLCanvasElement | undefined = $state();
    35		let animId: number | null = null;
    36		let particles: Particle[] = [];
    37	
    38		function initParticles(w: number, h: number) {
    39			particles = [];
    40			for (let i = 0; i < PARTICLE_COUNT; i++) {
    41				particles.push({
    42					x: Math.random() * w,
    43					y: Math.random() * h,
    44					vx: (Math.random() - 0.5) * 0.5,
    45					vy: (Math.random() - 0.5) * 0.4,
    46					size: 1 + Math.random() * 2,
    47					color: COLORS[Math.floor(Math.random() * COLORS.length)],
    48					opacity: 0.3 + Math.random() * 0.5,
    49					opacitySpeed: 0.003 + Math.random() * 0.005,
    50					opacityDir: Math.random() > 0.5 ? 1 : -1,
    51				});
    52			}
    53		}
    54	
    55		function animate() {
    56			if (!canvas) return;
    57			const ctx = canvas.getContext('2d');
    58			if (!ctx) return;
    59	
    60			const w = canvas.width;
    61			const h = canvas.height;
    62	
    63			ctx.clearRect(0, 0, w, h);
    64	
    65			for (const p of particles) {
    66				// Move
    67				p.x += p.vx;
    68				p.y += p.vy;
    69	
    70				// Wrap around edges
    71				if (p.x < -5) p.x = w + 5;
    72				if (p.x > w + 5) p.x = -5;
    73				if (p.y < -5) p.y = h + 5;
    74				if (p.y > h + 5) p.y = -5;
    75	
    76				// Fade in/out cycle
    77				p.opacity += p.opacitySpeed * p.opacityDir;
    78				if (p.opacity >= 0.8) { p.opacityDir = -1; }
    79				if (p.opacity <= 0.15) { p.opacityDir = 1; }
    80	
    81				// Draw
    82				ctx.globalAlpha = p.opacity;
    83				ctx.fillStyle = p.color;
    84				ctx.fillRect(
    85					Math.round(p.x),
    86					Math.round(p.y),
    87					Math.round(p.size),
    88					Math.round(p.size)
    89				);
    90			}
    91	
    92			ctx.globalAlpha = 1;
    93			animId = requestAnimationFrame(animate);
    94		}
    95	
    96		function startAnimation() {
    97			if (!canvas) return;
    98			canvas.width = window.innerWidth;
    99			canvas.height = window.innerHeight;
   100			initParticles(canvas.width, canvas.height);
   101			animId = requestAnimationFrame(animate);
   102		}
   103	
   104		function stopAnimation() {
   105			if (animId !== null) {
   106				cancelAnimationFrame(animId);
   107				animId = null;
   108			}
   109		}
   110	
   111		function handleResize() {
   112			if (!canvas || !ui.animationsEnabled) return;
   113			canvas.width = window.innerWidth;
   114			canvas.height = window.innerHeight;
   115			initParticles(canvas.width, canvas.height);
   116		}
   117	
   118		// Start/stop based on animationsEnabled
   119		$effect(() => {
   120			if (ui.animationsEnabled && canvas) {
   121				startAnimation();
   122				window.addEventListener('resize', handleResize);
   123			} else {
   124				stopAnimation();
   125			}
   126	
   127			return () => {
   128				stopAnimation();
   129				window.removeEventListener('resize', handleResize);
   130			};
   131		});
   132	
   133		onDestroy(() => {
   134			stopAnimation();
   135		});
   136	</script>
   137	
   138	{#if ui.animationsEnabled}
   139		<canvas
   140			bind:this={canvas}
   141			class="particles-canvas"
   142			aria-hidden="true"
   143		></canvas>
   144	{/if}
   145	
   146	<style>
   147		.particles-canvas {
   148			position: fixed;
   149			top: 0;
   150			left: 0;
   151			width: 100vw;
   152			height: 100vh;
   153			z-index: 0;
   154			pointer-events: none;
   155			image-rendering: pixelated;
   156		}
   157	</style>

