  44	fn send_events(tx: &mpsc::Sender<Vec<u8>>, events: Vec<MidiEvent>, pitch_bend_range: u8) {
  45	    for event in events {
  46	        #[cfg(debug_assertions)]
  47	        match &event {
  48	            MidiEvent::NoteOn { note, velocity, .. } => {
  49	                eprintln!("[guitar-midi] NoteOn note={note} velocity={velocity}");
  50	            }
  51	            MidiEvent::NoteOff { note, .. } => {
  52	                eprintln!("[guitar-midi] NoteOff note={note}");
  53	            }
  54	            _ => {}
  55	        }
  56	        let bytes = event.to_midi_bytes(pitch_bend_range);
  57	        if !bytes.is_empty() {
  58	            let _ = tx.send(bytes);
  59	        }
  60	    }
  61	}
