  81	    #[allow(clippy::too_many_arguments)]
  82	    pub fn new(
  83	        device_name: &str,
  84	        channel: usize,
  85	        config: GuitarInputConfig,
  86	        shared_config: Arc<Mutex<Option<GuitarInputConfig>>>,
  87	        calibration_profile: Option<GuitarCalibrationProfile>,
  88	        live_pipeline_handle: Option<Arc<Mutex<Option<Arc<Mutex<GuitarInput>>>>>>,
  89	        tx: mpsc::Sender<Vec<u8>>,
  90	        signal_tx: Option<mpsc::Sender<GuitarSignalInfo>>,
  91	    ) -> Result<Self, String> {
  92	        eprintln!(
  93	            "[guitar_bridge] Creating bridge: device='{}' channel={}",
  94	            device_name, channel
  95	        );
  96	        let host = cpal::default_host();
  97	        let device = if device_name.is_empty() {
  98	            host.default_input_device()
  99	                .ok_or("No default audio input device")?
 100	        } else {
 101	            host.input_devices()
 102	                .map_err(|e| format!("Failed to enumerate audio devices: {e}"))?
 103	                .find(|device| device.name().unwrap_or_default().contains(device_name))
 104	                .or_else(|| host.default_input_device())
 105	                .ok_or("No default audio input device")?
 106	        };
 107	        let supported_config = device
 108	            .default_input_config()
 109	            .map_err(|e| format!("No input config: {e}"))?;
 110	        let sample_rate = supported_config.sample_rate() as usize;
 111	        let channels = supported_config.channels() as usize;
 112	        if channel >= channels {
 113	            return Err(format!(
 114	                "Input channel {} is unavailable on a {}-channel device",
 115	                channel + 1,
 116	                channels
 117	            ));
 118	        }
 119	
 120	        eprintln!(
 121	            "[guitar_bridge] Found device: {} ({}ch {}Hz)",
 122	            device.name().unwrap_or_default(),
 123	            channels,
 124	            sample_rate
 125	        );
 126	
 127	        let mut actual_config = config;
 128	        actual_config.sample_rate = sample_rate;
 129	        let mut pipeline_inner = GuitarInput::new(actual_config.clone());
 130	        if let Some(profile) = calibration_profile {
 131	            pipeline_inner.set_calibration_profile(profile);
 132	        }
 133	        let pipeline = Arc::new(Mutex::new(pipeline_inner));
 134	        let pipeline_for_worker = Arc::clone(&pipeline);
 135	
 136	        // Cap queued audio at 100 ms. Overflow drops the backlog and forces
 137	        // All Notes Off rather than replaying stale detector output.
 138	        let audio_rb = HeapRb::<f32>::new(audio_queue_capacity(sample_rate));
 139	        let (mut audio_tx, mut audio_rx) = audio_rb.split();
 140	        let overflow = Arc::new(AtomicBool::new(false));
